'use strict';
const api=window.CallSheet,$=id=>document.getElementById(id);
function captureFailure(kind,error){api.request('diagnosticCapture',{kind,error:{name:error?.name,stack:error?.stack,code:error?.code}}).catch(()=>{});}
window.addEventListener('error',event=>captureFailure('renderer-error',event.error));
window.addEventListener('unhandledrejection',event=>captureFailure('renderer-unhandled-rejection',event.reason));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const Days=window.ShootingDays,Availability=window.Availability;
const clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>crypto.randomUUID();
let project,version,revisions=[],projects=[],dayId,view='daily',section='overview',master='general',dirty=0,saved=0,saveTimer,savePromise,previewTimer,previewSerial=0,toastTimer,boot,modalAction,previewObserver,lockedDisplay={},transitionQueue=Promise.resolve();
let visibleWeek,weekPage=0,undoDays=[],redoDays=[],productionBusy=false;
const readPreference=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
function writePreference(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('The app preference could not be saved on this device.');}}
function rememberDays(){if(project)writePreference('shooting-days:'+project.id,{dayId,visibleWeek,weekPage});}
function revealDay(){const g=Days.weeks(project.days).find(g=>g.days.some(d=>d.id===dayId));visibleWeek=g?.key;weekPage=Math.floor(Math.max(0,g?.days.findIndex(d=>d.id===dayId)??0)/7);rememberDays();}
function selectDay(id){dayId=id;revealDay();render();}
const day=()=>project.days.find(d=>d.id===dayId)||project.days[0];
const di=()=>project.days.findIndex(d=>d.id===dayId);
const locked=()=>!!day()?.lockedRevisionId;
const sheetLabels={header:'Company header / office contact',director:'Director',producer:'Producer',upm:'UPM',firstAD:'1st AD',secondAD:'2nd AD',breakfast:'Courtesy breakfast',shootingCall:'Shooting call',scriptColor:'Script revision color',scheduleColor:'Schedule revision color',safety:'Safety banner',walkies:'Walkie channels',departmentNotes:'Special instructions by department',basecamp:'Basecamp address / directions',hospitalNotes:'Hospital / route notes',parkingNotes:'Parking instructions',high:'High temperature (°C)',low:'Low temperature (°C)',weatherIcon:'Weather symbol'};
const sheetBase=()=>Object.fromEntries(Object.keys(sheetLabels).map(k=>[k,k==='safety'?'SAFETY FIRST | NO SMOKING ON SET | CHECK IN WITH PRODUCTION':k==='weatherIcon'?'None':'']));
const labels={overview:'Overview',logistics:'Locations & safety',schedule:'Schedule',cast:'Cast calls',crew:'Crew calls',notes:'Notes & advance',background:'Stand-ins & background',weather:'Weather & sun',layout:'Template & layout'};
const sectionLabel={logistics:'Locations & emergency',schedule:'Daily schedule',cast:'Cast calls',crew:'Crew calls',notes:'Production notes',advance:'Advance schedule'};
function toast(t){$('toast').textContent=String(t).replace(/^Error invoking remote method[^:]+: Error: /,'');$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function error(e){toast(e.message||e);}
function at(path){return path.split('.').reduce((a,k)=>a?.[k],project);}
function put(path,value){const keys=path.split('.');let obj=project;for(const k of keys.slice(0,-1))obj=obj[k];obj[keys.at(-1)]=value;}
function mark(){dirty++;refreshAvailabilityWarnings();$('save-state').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(error),400);schedulePreview();}
async function flush(){
 clearTimeout(saveTimer);if(savePromise){await savePromise;if(saved<dirty)return flush();return;}
 savePromise=(async()=>{while(saved<dirty){const target=dirty,payload=clone(project);try{const result=await api.request('save',{project:payload,version});version=result.version;revisions=result.revisions;saved=target;projects=projects.map(p=>p.id===payload.id?{...p,title:payload.title,version:result.version}:p);const option=[...$('production').options].find(o=>o.value===payload.id);if(option)option.textContent=payload.title+(payload.demo?' · Demo':'');$('save-state').textContent='Saved on this device';}catch(e){$('save-state').textContent='Save failed - click Save to retry';throw e;}}})();
 try{await savePromise;}finally{savePromise=null;}
}
async function useState(state){const changed=project?.id!==state.project.id;project=state.project;const pref=readPreference('shooting-days:'+project.id,{});if(changed){dayId=pref.dayId;visibleWeek=pref.visibleWeek;weekPage=Number.isSafeInteger(pref.weekPage)?pref.weekPage:0;undoDays=[];redoDays=[];resetAvailabilityUI();}project.sheetDefaults={...sheetBase(),...project.sheetDefaults};project.days.forEach(d=>{d.sheetOverrides||={};d.background||=[];d.layout.sceneColors??=true;});version=state.version;revisions=state.revisions;dirty=0;saved=0;dayId=project.days.find(d=>d.id===dayId)?.id||project.days[0]?.id;projects=await api.request('list');render();}
function transition(fn){const run=async()=>{try{await flush();await fn();}catch(e){error(e);renderSide();}};transitionQueue=transitionQueue.then(run,run);return transitionQueue;}
function effective(k){if(Object.hasOwn(day().overrides,k))return day().overrides[k];return project.defaults[k]??'';}
function primaryLocation(){return project.locations.find(l=>l.id===effective('primaryLocationId'));}
function effectiveZone(){return Object.hasOwn(day().overrides,'zone')?day().overrides.zone:primaryLocation()?.zone||project.defaults.zone;}
function options(items,value,empty='Select…'){return (empty!==null?`<option value="">${esc(empty)}</option>`:'')+items.map(x=>`<option value="${esc(typeof x==='string'?x:x.id)}" ${(typeof x==='string'?x:x.id)===value?'selected':''}>${esc(typeof x==='string'?x:x.name||x.label)}</option>`).join('');}
function field(label,path,type='text',config={}){
 const value=config.value!==undefined?config.value:at(path),disabled=config.disabled||locked()&&view!=='production';
 const attrs=`data-bind="${path}" ${disabled?'disabled':''} ${config.extra||''}`;
 const input=type==='textarea'?`<textarea ${attrs} rows="${config.rows||3}">${esc(value)}</textarea>`:type==='select'?`<select ${attrs}>${options(config.items||[],value,config.empty===undefined?'Select…':config.empty)}</select>`:type==='checkbox'?`<input type="checkbox" ${attrs} ${value?'checked':''}>`:`<input ${attrs} type="${type}" value="${esc(value)}" ${type==='number'?'step="any"':''}>`;
 return `<label class="field ${config.wide?'wide':''}">${esc(label)}${input}${config.note?`<small>${config.note}</small>`:''}</label>`;
}
function inherited(label,key,type='text',config={}){
 const inherited=!Object.hasOwn(day().overrides,key),path=`days.${di()}.overrides.${key}`;
 return field(label,path,type,{...config,value:key==='zone'?effectiveZone():effective(key),note:`${inherited?(key==='zone'&&primaryLocation()?.zone?'Location default':'Production default'):'Day override'}${!inherited&&!locked()?` <button data-reset="${key}" type="button">Reset to default</button>`:''}`});
}
function shell(title,body,toolbar=''){return `<div class="panel"><div class="panel-header"><span class="panel-title">${esc(title)}</span>${toolbar}</div><div class="panel-body">${body}</div></div>`;}
function renderSide(){
 $('production').innerHTML=options(projects.map(p=>({id:p.id,name:p.title+(p.demo?' · Demo':'')})),project?.id,null);
 const groups=Days.weeks(project?.days||[]);let group=groups.find(g=>g.key===visibleWeek)||groups.find(g=>g.days.some(d=>d.id===dayId))||groups[0];visibleWeek=group?.key;weekPage=Math.max(0,Math.min(weekPage,Math.ceil((group?.days.length||1)/7)-1));const wi=groups.indexOf(group),shown=group?.days.slice(weekPage*7,weekPage*7+7)||[];
 $('week-navigation').innerHTML=group?`<div class="week-nav"><button data-week-step="-1" aria-label="Previous shoot week" ${wi===0?'disabled':''}>←</button><span>Week ${wi+1} of ${groups.length}<small>${esc(weekLabel(group))}</small></span><button data-week-step="1" aria-label="Next shoot week" ${wi===groups.length-1?'disabled':''}>→</button></div>${group.days.length>7?`<div class="week-nav"><button data-week-page="-1" ${weekPage===0?'disabled':''} aria-label="Previous seven days">←</button><span>${weekPage*7+1}–${Math.min(group.days.length,weekPage*7+7)} of ${group.days.length}</span><button data-week-page="1" ${weekPage*7+7>=group.days.length?'disabled':''} aria-label="Next seven days">→</button></div>`:''}${!shown.some(d=>d.id===dayId)?'<button data-reveal-day class="text-button">Show selected day</button>':''}`:'<p class="tiny">No shooting days</p>';
 $('undo-day').disabled=!undoDays.length;$('redo-day').disabled=!redoDays.length;$('deleted-days').textContent=`Deleted days (${project.deletedDays?.length||0})`;
 $('days').innerHTML=shown.map(d=>{const r=revisions.find(r=>r.id===d.lockedRevisionId);return `<div class="day-entry"><button aria-current="${d.id===dayId?'date':'false'}" class="day-row ${d.id===dayId?'active':''}" data-day="${d.id}"><strong>${esc(d.label)}</strong><small>${esc(d.date||'Date needed')} / Unit ${esc(d.unit)}</small><em>${r?'R'+r.number:'Draft'}</em></button><button class="day-options" data-day-options="${d.id}" aria-label="Actions for ${esc(d.label)}" title="Change date or delete">⋯</button></div>`;}).join('');rememberDays();
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
}
function renderHeader(){
 document.body.dataset.projectId=project.id;
 const d=day();for(const id of ['duplicate-day','export-pdf','issue'])$(id).disabled=!d;if(!d){$('breadcrumb').textContent=`Workspace / ${project.title}`;$('heading').textContent='No shooting days';$('subtitle').textContent='Add a shooting day or restore one from Deleted days.';$('summary').innerHTML='';$('previous').disabled=true;$('next').disabled=true;$('project-notice').hidden=true;return;}const loc=primaryLocation(),r=revisions.find(r=>r.id===d.lockedRevisionId),frozen=lockedDisplay[project.id+':'+d.lockedRevisionId];
 $('breadcrumb').textContent=`Workspace / ${project.title} / ${d.label}`;$('heading').textContent=view==='production'?'Production data':view==='revisions'?'Issued revisions':view==='layout'?'Templates & layout':`${d.label} - Unit ${d.unit}`;
 $('eyebrow').textContent=view==='production'?'REUSABLE PRODUCTION REGISTER':view==='revisions'?'PRESERVED ISSUED ARTIFACTS':'DAILY CALL SHEET';
 $('subtitle').textContent=view==='production'?'Common records feed every draft. Issued sheets stay frozen.':view==='revisions'?'Original PDFs remain unchanged as your production evolves.':`${d.date||'Set a shooting date'} / ${locked()?(frozen?.zone||'Issued timezone in preview'):effectiveZone()||'Choose a timezone'}`;
 const stats=[['GENERAL CALL',locked()?(frozen?.generalCall||'Issued preview'):effective('generalCall')||'Required'],['LOCATION',locked()?(frozen?.location||'Issued preview'):loc?.name||'Required'],['TEMPLATE',({gcasper:'G-Casper-style',narrative:'Original Narrative',compact:'Compact Crew',commercial:'Commercial / Documentary'})[d.layout.preset]],['STATE',r?'Issued R'+r.number:'Draft']];
 $('summary').innerHTML=stats.map(([a,b])=>`<div class="summary-stat"><small>${a}</small><strong>${esc(b)}</strong></div>`).join('')+`<p class="summary-note">${project.scenes.length} scenes / ${project.days.length} shooting days${project.productionDesk?'<br><button data-action="source-details">Source details</button>':''}</p>`;
 const ordered=Days.ordered(project.days),position=ordered.findIndex(d=>d.id===dayId);$('previous').disabled=position<=0;$('next').disabled=position===ordered.length-1;$('issue').textContent=locked()?'Create new draft':'Review & issue';
 $('project-notice').hidden=!project.demo;$('project-notice').textContent=project.demo?'This saved production contains fictional example data. Review all people, calls, locations and emergency details before operational use.':'';
}
function sheetField(key,production=false){const value=production?project.sheetDefaults[key]:Object.hasOwn(day().sheetOverrides,key)?day().sheetOverrides[key]:project.sheetDefaults[key],path=production?'sheetDefaults.'+key:`days.${di()}.sheetOverrides.${key}`,type=['breakfast','shootingCall'].includes(key)?'time':['high','low'].includes(key)?'text':['header','safety','walkies','departmentNotes','basecamp','hospitalNotes','parkingNotes'].includes(key)?'textarea':['weatherIcon','scriptColor','scheduleColor'].includes(key)?'select':'text';return field(sheetLabels[key],path,type,{value,wide:type==='textarea',items:key==='weatherIcon'?['None','Sunny','Partially cloudy','Cloudy','Light rain','Rain','Clear night','Cloudy night']:['','White','Blue','Pink','Yellow','Green','Goldenrod','Buff','Salmon','Cherry','Tan','Gray','Ivory'],empty:null,note:production?'Reusable across inheriting days':Object.hasOwn(day().sheetOverrides,key)?`Day override <button data-sheet-reset="${key}" type="button">Reset to production</button>`:'Production default'});}
function overview(){
 const d=day();return `<div class="form-grid">${field('Shooting day label',`days.${di()}.label`)}${field('Unit',`days.${di()}.unit`)}${field('Shoot date',`days.${di()}.date`,'date',{note:'Rescheduling preserves day identity. Weather approval resets.'})}${inherited('General crew call','generalCall','time')}${sheetField('breakfast')}${sheetField('shootingCall')}${sheetField('scriptColor')}${sheetField('scheduleColor')}${inherited('Meal','meal','time')}${inherited('Estimated wrap','wrap','time')}${inherited('Primary location','primaryLocationId','select',{items:project.locations,wide:true})}${inherited('Timezone override','zone','text',{wide:true,note:'Location timezone is used unless you override it here.'})}</div><p class="inline-notice">${locked()?'This day is issued. Create a new draft to edit it.':'Common production values are inherited until you change them here. A blank override stays blank.'}</p>`;
}
function logistics(){
 const loc=primaryLocation();if(!loc)return '<p class="empty">Choose a primary location in Overview, or add one in Production data.</p>';
 return `<h3>${esc(loc.name)}</h3><p class="tiny">Production record. Edit it in Production data → Locations to update drafts.</p><div class="inline-notice"><p>${esc(loc.address)}</p><p>Parking: ${esc(loc.parking)}</p><p>Emergency facility: ${esc(loc.hospital)}</p><p>Emergency contact: ${esc(loc.emergencyPhone)}</p><p>${loc.verified?'Reviewed by production':'Verification required before issue'}</p></div><button data-action="edit-locations">Edit production locations</button><div class="form-grid">${['basecamp','hospitalNotes','parkingNotes'].map(k=>sheetField(k)).join('')}</div>`;
}
function schedule(){
 const d=day(),prefix=`days.${di()}.schedule`;
 return `${!locked()?`<div class="toolbar"><select id="add-scene-select" aria-label="Scene to add">${options(project.scenes.map(s=>({id:s.id,name:s.number+' · '+s.slug})),'')}</select><button data-action="add-scene">Add scene & cast</button><button data-action="add-break">+ Break / move</button></div>`:''}${d.schedule.length?d.schedule.map((s,i)=>{const sc=project.scenes.find(a=>a.id===s.sceneId),p=prefix+'.'+i;return `<article class="row-card"><div class="row-title"><strong>${esc(sc?sc.number+' · '+sc.slug:s.type.toUpperCase())}</strong>${!locked()?`<button data-move="schedule:${i}:-1" aria-label="Move schedule item up">↑</button><button data-move="schedule:${i}:1" aria-label="Move schedule item down">↓</button><button data-remove="schedule:${i}" aria-label="Remove schedule item">×</button>`:''}</div><div class="form-grid">${field('Start',p+'.start','time')}${field('Day offset',p+'.offset','number',{extra:'min="0" max="3" step="1"'})}${field('Minutes',p+'.duration','number',{extra:'min="0" max="1440" step="1"'})}${s.type!=='scene'?field('Type',p+'.type','select',{items:['meal','move','break','note'],empty:null}):'<p class="tiny">'+esc(sc.eighths)+' eighths / '+esc(sc.durationMinutes||s.duration)+' min source estimate</p>'}${field('Description override',p+'.description','textarea',{wide:true,note:sc?esc(sc.synopsis):''})}</div>${sc?`<button class="text-button" data-script="${sc.id}">View scene & source details</button>`:''}</article>`;}).join(''):'<p class="empty">Build the day from your production scene register. Add breaks and company moves as needed.</p>'}`;
}
function calls(type){
 const d=day(),people=project.people.filter(p=>p.type===type);return `<p class="tiny">Blank personal call inherits general crew call (${esc(effective('generalCall'))}). Add a day offset for overnight calls.</p>${people.length?people.map(who=>{const i=d.calls.findIndex(c=>c.personId===who.id),c=d.calls[i],p=`days.${di()}.calls.${i}`;return `<article class="row-card" data-availability-person="${who.id}"><div class="row-title"><strong>${esc(who.name)}<small class="tiny"> / ${esc(who.character||who.role||who.department)}</small></strong><label class="check"><input type="checkbox" data-attend="${who.id}" ${c?'checked':''} ${locked()?'disabled':''}> Called</label></div><div class="call-availability"></div>${c?`<div class="form-grid">${field('Personal call',p+'.call','time',{note:c.call?'Day override':'Inherits '+esc(effective('generalCall'))})}${field('Day offset',p+'.offset','number',{extra:'min="0" max="3" step="1"'})}${type==='cast'?field('Pickup',p+'.pickup','time')+field('Makeup',p+'.makeup','time')+field('Wardrobe',p+'.wardrobe','time')+field('Blocking / rehearsal',p+'.block','time')+field('Ready / on set',p+'.ready','time')+field('Lose at',p+'.loseAt','time')+field('Status',p+'.status'):field('Release / end',p+'.loseAt','time',{note:'Earlier than call means next local day. Blank uses estimated wrap / scheduled work.'})+field('Status / call label (e.g. O/C)',p+'.status')}${field('Day notes',p+'.notes','textarea',{wide:true})}</div>`:''}</article>`;}).join(''):'<p class="empty">Add '+type+' in Production data first.</p>'}`;
}
function notes(){return `<div class="form-grid">${inherited('Production notes','notes','textarea',{wide:true,rows:6})}${['safety','departmentNotes','walkies','header','director','producer','upm','firstAD','secondAD'].map(k=>sheetField(k)).join('')}${field('Advance schedule override',`days.${di()}.advance`,'textarea',{wide:true,rows:5,note:'Leave blank for the next shooting day’s scenes in G-Casper-style output.'})}</div>`;}
function background(){const p=`days.${di()}.background`;return `<p class="tiny">Daily quantities feed the front sheet and catering totals.</p><button data-action="add-background">+ Add stand-ins / background</button>${day().background.map((b,i)=>`<article class="row-card"><div class="form-grid">${field('Type',p+`.${i}.type`,'select',{items:['stand-in','background'],empty:null})}${field('Quantity',p+`.${i}.quantity`,'number',{extra:'min="0" max="10000" step="1"'})}${field('Description',p+`.${i}.description`)}${field('Call',p+`.${i}.call`,'time')}${field('Instructions',p+`.${i}.notes`,'textarea',{wide:true})}</div><button data-remove="background:${i}">Remove</button></article>`).join('')}`;}
function weather(){
 const d=day(),loc=primaryLocation(),p=`days.${di()}.weather`;return `<p class="tiny">Forecasts need an internet request. Sunrise and sunset calculate locally from the selected location/date; no location is transmitted for solar calculations.</p><div class="form-grid">${field('Weather summary',p+'.summary','textarea',{wide:true,rows:4})}${['high','low','weatherIcon'].map(k=>sheetField(k)).join('')}${field('Weather reviewed for this date / location',p+'.approved','checkbox',{wide:true})}</div><div class="inline-notice"><p>Mode: ${esc(d.weather.mode)}. ${d.weather.fetchedAt?'Retrieved '+esc(d.weather.fetchedAt):'No online forecast requested.'}</p><p>${loc?.latitude===null||!loc?'Enter coordinates in Production data → Locations to enable offline solar and optional forecasts.':'Coordinates: '+esc(loc.latitude)+', '+esc(loc.longitude)+' / '+esc(effectiveZone())}</p></div><div class="toolbar"><button data-action="forecast" ${locked()?'disabled':''}>Get NWS forecast…</button><button data-action="manual-weather" ${locked()?'disabled':''}>Use manual / offline</button></div><p class="tiny">NWS covers supported US locations for about 7 days. Future dates and outages stay explicitly unavailable. Requests never include cast, crew or the production title.</p>`;
}
function layout(){
 const d=day(),p=`days.${di()}.layout`;return `<div class="template-cards">${[['gcasper','G-Casper-style','Dense front + three-column crew back'],['narrative','Original Narrative','The original flowing Production Desk design']].map(([id,name,desc])=>`<button class="template-card ${d.layout.preset===id?'selected':''}" data-template="${id}"><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="form-grid">${field('Preset',p+'.preset','select',{items:[{id:'gcasper',name:'G-Casper-style · front & back (default)'},{id:'compact',name:'Compact Crew'},{id:'narrative',name:'Original Narrative'},{id:'commercial',name:'Commercial / Documentary'}],empty:null})}${field('Paper',p+'.paper','select',{items:['A4','Letter'],empty:null})}${field('Clock',p+'.clock','select',{items:[{id:'24',name:'24-hour'},{id:'12',name:'12-hour'}],empty:null})}${field('Temperature preference',p+'.temperature','select',{items:['C','F'],empty:null})}${field('Save toner / ink (monochrome)',p+'.mono','checkbox')}${field('D/N and INT/EXT scene strip colors',p+'.sceneColors','checkbox')}${field('Include personal phone / email in PDF',p+'.includeContacts','checkbox')}</div><p class="inline-notice">The same day data is kept when templates change. Hidden sections remain editable. Emergency logistics always prints. G-Casper-style keeps crew on a separate back; section order controls the front. Dense content continues onto extra pages. Existing saved template choices are preserved.</p><h3>Section order & visibility</h3><div class="section-order">${d.layout.order.map((k,i)=>`<div><span>${esc(sectionLabel[k])}</span><label><input data-hide="${k}" type="checkbox" ${!d.layout.hidden.includes(k)?'checked':''} ${locked()||k==='logistics'?'disabled':''}> Show</label><button data-move="layout:${i}:-1" ${locked()?'disabled':''} aria-label="Move section up">↑</button><button data-move="layout:${i}:1" ${locked()?'disabled':''} aria-label="Move section down">↓</button></div>`).join('')}</div><h3 class="row-card">Custom sections</h3>${d.layout.custom.map((c,i)=>`<article class="row-card"><div class="form-grid">${field('Heading',p+`.custom.${i}.title`,'text',{wide:true})}${field('Text',p+`.custom.${i}.text`,'textarea',{wide:true})}</div>${!locked()?`<button class="text-button" data-remove="custom:${i}">Remove section</button>`:''}</article>`).join('')}<button data-action="custom-section" ${locked()?'disabled':''}>+ Add custom section</button>`;
}
function renderDaily(){
 const d=day(),current=view==='layout'?'layout':section,body=locked()?'<div class="inline-notice"><h3>Issued snapshot</h3><p>The preview shows the approved values from this revision. Its original PDF exports unchanged. Production registers may continue to evolve.</p><p>Create a new draft to edit this day using current production records.</p></div>':({overview,logistics,schedule,cast:()=>calls('cast'),crew:()=>calls('crew'),notes,background,weather,layout}[current])();
 $('content').innerHTML=`${locked()?`<div class="locked"><span>Issued revision is frozen. Its original PDF will export unchanged.</span><button data-action="new-draft">Create new draft</button></div>`:''}<div id="availability-alerts" aria-live="polite"></div><div class="workspace"><aside class="panel"><div class="panel-header"><span class="panel-title">Sheet sections</span></div><div class="section-nav">${Object.entries(labels).map(([k,t])=>`<button data-section="${k}" class="${k===current?'active':''}">${t}</button>`).join('')}</div></aside><div class="panel"><div class="panel-header"><span class="panel-title">${esc(labels[current])}</span><span class="tiny">${locked()?'READ ONLY':'AUTOSAVE'}</span></div><div class="panel-body editor-scroll">${body}</div></div><section class="panel preview-panel"><div class="panel-header"><span class="panel-title">Print preview</span><div class="preview-tools"><button data-action="refresh-preview">Refresh</button><button data-action="pdf">PDF</button></div></div><div class="preview-wrap"><iframe title="Call sheet print preview" id="preview" sandbox="allow-same-origin"></iframe></div><p class="tiny panel-body" id="preview-note">Loading local preview…</p></section></div>`;
 bindFields();refreshAvailabilityWarnings();refreshPreview();
}
function masterGeneral(){return `<div class="form-grid">${field('Production title','title','text',{wide:true})}${field('Company','company','text',{wide:true})}${field('Default general call','defaults.generalCall','time')}${field('Default timezone','defaults.zone')}${field('Default meal','defaults.meal','time')}${field('Default wrap','defaults.wrap','time')}${field('Default location','defaults.primaryLocationId','select',{items:project.locations,wide:true})}${field('Recurring production notes','defaults.notes','textarea',{wide:true,rows:5})}${Object.keys(sheetLabels).map(k=>sheetField(k,true)).join('')}</div><div class="inline-notice">Changes feed every inheriting draft immediately. Issued PDFs retain their approved values. A daily override takes precedence.</div>`;}
function masterPeople(type){return `${type==='crew'?'<datalist id="crew-departments">'+window.CrewDepartments.map(name=>'<option value="'+esc(name)+'"></option>').join('')+'</datalist>':''}<div class="toolbar"><button class="primary" data-action="add-${type}">+ Add ${type==='cast'?'cast member':'crew member'}</button><button data-action="availability-${type}">${type==='cast'?'Cast':'Crew'} availability</button></div>${project.people.map((p,i)=>p.type!==type?'':`<article class="master-card"><div class="master-head"><h3>${esc(p.name||'New person')}</h3><span class="badge">${esc(p.character||p.role||type)}</span></div><div class="form-grid">${field('Name',`people.${i}.name`)}${field(type==='cast'?'Character':'Role',`people.${i}.${type==='cast'?'character':'role'}`)}${field('Department',`people.${i}.department`,'text',type==='crew'?{extra:'list="crew-departments" autocomplete="off"',note:'Choose a suggestion or type your own department.'}:{})}${field('Email',`people.${i}.email`,'email')}${field('Phone',`people.${i}.phone`,'tel')}${type==='cast'?field('Cast ID / number',`people.${i}.castNumber`):''}${field('Catering category / food preference',`people.${i}.diet`,'text',{note:'Optional. Daily PDF shows category counts, without names.'})}</div></article>`).join('')}`;}
function locationMapInfo(loc,kind){
 const parking=kind==='parking',link=loc[parking?'parkingMapsUrl':'mapsUrl']||'',address=loc[parking?'parking':'address'],info=window.LocationMaps.inspect(link),key=esc(loc.id)+':'+kind;
 const message=info.status==='invalid'?'Use a full HTTPS Google Maps link. Other sites and invalid links cannot be opened.':info.status==='short'?'Short link: open Google Maps to read/copy the address, then enter it below.':info.status==='no-address'?'No address text is embedded in this link. Open the map and enter the address manually.':info.status==='text'?'Text found in the link (review it; it may be a place name rather than a street address): '+info.text:'Paste a Google Maps link or enter a manual address. An address can also be opened as a Maps search.';
 return `<p class="tiny" role="status">${esc(message)}</p><div class="toolbar">${info.text&&info.text!==address?`<button data-map-use="${key}">${address?'Replace address with link text':'Use link text as address'}</button>`:''}<button data-map-open="${key}" ${info.status==='invalid'||!info.url&&!address.trim()?'disabled':''}>Open ${parking?'parking / base camp':'shooting location'} in Google Maps ↗</button></div>`;
}
function locationMapFields(loc,i,kind){const parking=kind==='parking',p=`locations.${i}`;return `<fieldset class="location-place"><legend>${parking?'Parking / base camp':'Shooting location'}</legend><div class="form-grid">${field('Google Maps link',p+(parking?'.parkingMapsUrl':'.mapsUrl'),'text',{wide:true,extra:'inputmode="url" spellcheck="false"',note:'Optional. Link text is inspected on this device; your address is never replaced automatically.'})}<div class="wide" data-map-info="${esc(loc.id)}:${kind}">${locationMapInfo(loc,kind)}</div>${field(parking?'Parking / base camp address or directions':'Address',p+(parking?'.parking':'.address'),'textarea',{wide:true,rows:2,note:'Editable manually. This text appears on draft call sheets.'})}</div></fieldset>`;}
function refreshLocationMapInfo(path){const m=path.match(/^locations\.(\d+)\.(?:mapsUrl|parkingMapsUrl|address|parking)$/);if(!m)return;const loc=project.locations[Number(m[1])];if(!loc)return;document.querySelectorAll('[data-map-info]').forEach(el=>{for(const kind of ['shoot','parking'])if(el.dataset.mapInfo===loc.id+':'+kind)el.innerHTML=locationMapInfo(loc,kind);});}
function masterLocations(){return `<div class="toolbar"><button class="primary" data-action="add-location">+ Add location</button></div><p class="tiny">Opening a map uses your browser and sends its link or search address to Google. Address suggestions work offline only when text is embedded in the link. Short links, place IDs and coordinate-only links need manual address entry; no online lookup or paid API is used.</p>${project.locations.map((l,i)=>{const p=`locations.${i}`;return `<article class="master-card"><div class="master-head"><h3>${esc(l.name||'New location')}</h3><span class="badge">${l.verified?'Reviewed':'Needs review'}</span></div><div class="form-grid">${field('Location name',p+'.name')}${field('IANA timezone',p+'.zone')}</div>${locationMapFields(l,i,'shoot')}${locationMapFields(l,i,'parking')}<div class="form-grid">${field('Emergency facility / route',p+'.hospital','textarea',{wide:true})}${field('Emergency contact',p+'.emergencyPhone')}${field('Facility details verified by production',p+'.verified','checkbox')}</div><details class="location-advanced"><summary>Advanced · latitude and longitude</summary><p class="tiny">Coordinates are optional and never inferred from the map camera position. Shooting coordinates still drive solar/weather. Parking coordinates are separate.</p><div class="form-grid">${field('Shooting latitude',p+'.latitude','number',{extra:'min="-90" max="90"',note:'Blank is unknown, not 0°.'})}${field('Shooting longitude',p+'.longitude','number',{extra:'min="-180" max="180"'})}${field('Parking / base camp latitude',p+'.parkingLatitude','number',{extra:'min="-90" max="90"'})}${field('Parking / base camp longitude',p+'.parkingLongitude','number',{extra:'min="-180" max="180"'})}</div></details></article>`;}).join('')}`;}

function masterScenes(){return `<div class="toolbar"><button class="primary" data-action="add-scene-master">+ Add scene</button></div>${project.scenes.map((s,i)=>{const p=`scenes.${i}`,used=project.days.filter(d=>d.schedule.some(item=>item.sceneId===s.id));return `<article class="master-card"><div class="master-head"><h3>${esc(s.number)} · ${esc(s.slug)}</h3><span class="badge">${used.length?used.map(d=>esc(d.label)).join(', '):'Unscheduled'}</span><button data-script="${s.id}" class="text-button">Scene & shots</button></div><div class="form-grid">${field('Scene number',p+'.number')}${field('Slugline',p+'.slug')}${field('Pages in eighths',p+'.eighths','number',{extra:'min="0" max="8000" step="1"'})}${field('Location',p+'.locationId','select',{items:project.locations})}${field('Script day',p+'.scriptDay')}${field('Day / night code',p+'.dayNight')}${field('Department notes',p+'.notes','textarea',{wide:true})}${field('Synopsis',p+'.synopsis','textarea',{wide:true})}</div><p class="tiny">Cast: ${project.people.filter(p=>p.type==='cast').map(who=>`<label class="check"><input type="checkbox" data-scene-cast="${i}:${who.id}" ${s.castIds.includes(who.id)?'checked':''}> ${esc(who.character||who.name)}</label>`).join('')}</p></article>`;}).join('')}`;}
function renderProduction(){
 const tabs={general:'Production',cast:'Cast',crew:'Crew',locations:'Locations',scenes:'Scenes'},body=master==='general'?masterGeneral():master==='locations'?masterLocations():master==='scenes'?masterScenes():masterPeople(master);
 $('content').innerHTML=`<div class="master-layout"><section class="panel"><div class="master-tabs">${Object.entries(tabs).map(([k,v])=>`<button data-master="${k}" class="${k===master?'active':''}">${v}</button>`).join('')}</div><div class="panel-body master-list">${body}</div></section><aside class="panel help-panel"><div class="panel-body"><h3>Enter once. Reuse every day.</h3><p>Production records feed daily sheets by reference. Scene membership can help populate cast calls.</p><p>Contacts stay off PDFs unless explicitly included in the layout settings. Optional catering categories are counted for called people. Enter only information appropriate for the local project archive.</p><p>All edits save to a local SQLite database. Export a project archive for handoff or a portable backup.</p><p>${project.provenance?esc(project.provenance.source):'Your own production'}</p></div></aside></div>`;bindFields();
}
function renderRevisions(){
 $('content').innerHTML=shell('Issued revisions',revisions.length?revisions.map(r=>{const d=[...project.days,...(project.deletedDays||[])].find(d=>d.id===r.dayId);return `<article class="revision-card"><div><h3>${esc(d?.label||'Shooting day')} / R${r.number}</h3><p>${esc(r.issued)}</p><p>SHA-256 ${esc(r.hash.slice(0,20))}…</p></div><div><button data-revision-preview="${r.id}">View snapshot</button> <button data-revision-export="${r.id}">Export original PDF</button></div></article>`;}).join(''):'<p class="empty">No issued sheets yet. Finish a draft, review it, then issue a numbered revision.</p>');
}
function render(){previewSerial++;renderSide();renderHeader();if(view==='production')renderProduction();else if(view==='revisions')renderRevisions();else if(day())renderDaily();else $('content').innerHTML=shell('Shooting days','<p class="empty">This production has no active shooting days. Production records and issued revisions are retained. Add a day using +, or restore a deleted day.</p>');}
function bindFields(){
 document.querySelectorAll('[data-bind]').forEach(el=>el.addEventListener('input',()=>{
  if(!el.checkValidity()){el.reportValidity();return;}
  const path=el.dataset.bind;let value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''&&/(?:latitude|longitude|parkingLatitude|parkingLongitude)$/.test(path)?null:Number(el.value)):el.value;
  if(/^days\.\d+\.date$/.test(path)){if(!Days.validDate(value))return;const inverse=Days.apply(project,{kind:'date',id:day().id,date:value});undoDays.push(inverse);redoDays=[];revealDay();mark();renderHeader();renderSide();return;}
  put(path,value);refreshLocationMapInfo(path);if(path.includes('.sheetOverrides.')){const note=el.closest('label').querySelector('small');if(note)note.innerHTML=`Day override <button data-sheet-reset="${path.split('.').at(-1)}" type="button">Reset to production</button>`;}
  if(/(\.date|\.zone|latitude|longitude|primaryLocationId)$/.test(path)){for(const d of project.days)d.weather.approved=false;}
  if(/weather\.summary$/.test(path)&&day().weather.mode==='nws'){day().weather.mode='manual';delete day().weather.key;delete day().weather.fetchedAt;day().weather.approved=false;}
  mark();renderHeader();if(/layout\.preset$/.test(path))renderDaily();
 }));
}
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>refreshPreview().catch(error),550);}
function fitPreview(frame){const fit=()=>{if(!frame?.isConnected)return;const doc=frame.contentDocument;if(!doc?.body)return;const width=day().layout.paper==='Letter'?816:794;doc.documentElement.style.zoom=String(Math.min(1,Math.max(.2,frame.clientWidth/width)));frame.style.height=Math.ceil(doc.body.getBoundingClientRect().height+25)+'px';};frame.onload=()=>frame.contentDocument.fonts.ready.then(fit);previewObserver?.disconnect();previewObserver=new ResizeObserver(fit);previewObserver.observe(frame.parentElement);}
async function refreshPreview(){if(!$('preview')||!day())return;const serial=++previewSerial;try{await flush();const result=await api.request('preview',{projectId:project.id,dayId});if(serial!==previewSerial||!$('preview'))return;if(locked()){lockedDisplay[project.id+':'+day().lockedRevisionId]=result.display;renderHeader();}const frame=$('preview');fitPreview(frame);frame.srcdoc=result.html;$('preview-note').textContent=locked()?'Preserved issued values / original PDF retained':`Draft preview / ${day().layout.paper} / ${result.review.errors.length} required fixes / ${result.review.warnings.length} review notes`;}catch(e){if(serial===previewSerial&&$('preview-note'))$('preview-note').textContent='Preview not updated: '+e.message;}}
function modal(title,body,actions=[]){$('modal-body').onclick=null;$('modal-body').onchange=null;$('modal-body').onkeydown=null;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-error').textContent='';$('modal-actions').innerHTML='<button data-modal-cancel>Cancel</button>'+actions.map((a,i)=>`<button data-modal-action="${i}" class="${a.primary?'primary':''} ${a.danger?'danger':''}">${esc(a.label)}</button>`).join('');modalAction=actions;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(!productionBusy)$('modal').close();}
$('modal').addEventListener('cancel',e=>{if(productionBusy)e.preventDefault();});
function addCall(personId){if(day().calls.some(c=>c.personId===personId))return;day().calls.push({id:uid(),personId,call:'',offset:0,pickup:'',makeup:'',ready:'',notes:''});}
function addDayData(date,label){return {id:uid(),label,date,unit:day()?.unit||'A',overrides:{},sheetOverrides:{},background:[],schedule:[],calls:[],weather:{mode:'manual',summary:'',approved:false},layout:clone(day()?.layout||{preset:'gcasper',sceneColors:true,paper:'A4',clock:'24',temperature:'C',mono:false,includeContacts:false,order:Object.keys(sectionLabel),hidden:[],custom:[]}),baseRevisionId:null};}
function dayDialog(duplicate=false){const initialDate=duplicate?(day()?.date||new Date().toISOString().slice(0,10)):Days.nextDayDate(project.days);modal(duplicate?'Duplicate shooting day':'Add shooting day',`<div class="form-grid"><label class="field">Day label<input id="new-day-label" value="Day ${String(project.days.length+1).padStart(2,'0')}"></label><label class="field">Date<input type="date" id="new-day-date" value="${esc(initialDate)}"></label></div><p>${duplicate?'A separate draft will copy calls, schedule and layout. Weather approval and issued state reset.':'Days have stable identities independent of their dates. Multiple units can share one date.'}</p>`,[{label:duplicate?'Create copy':'Add day',primary:true,run:async()=>{const date=$('new-day-date').value;if(!date)throw Error('Choose a shooting date.');let d=duplicate?clone(day()):addDayData(date,$('new-day-label').value);d.id=uid();d.label=$('new-day-label').value||'New day';d.date=date;d.lockedRevisionId=null;d.baseRevisionId=null;d.weather={mode:'manual',summary:'',approved:false};d.calls.forEach(c=>c.id=uid());d.schedule.forEach(c=>c.id=uid());project.days.push(d);dayId=d.id;revealDay();mark();await flush();closeModal();render();}}]);}
function weekLabel(g){return g.key==='undated'?'Dates needed':`${g.key} – ${g.end}`;}
function chooseWeek(key){const g=Days.weeks(project.days).find(g=>g.key===key);if(!g)return;visibleWeek=key;weekPage=0;dayId=g.days[0].id;render();}
function daysOverview(){const groups=Days.weeks(project.days);modal('All shooting days',`<p>Calendar weeks run Monday–Sunday. Gaps are retained; weeks without shooting days are skipped. Equal dates keep production order. Sidebar shows up to seven records at a time.</p><div class="weeks-overview">${groups.map((g,i)=>`<section class="shoot-week ${g.key===visibleWeek?'selected-week':''}"><header><h3>Week ${i+1} · ${esc(weekLabel(g))}</h3><button data-choose-week="${g.key}">Choose week ${i+1}</button></header><div class="week-strip">${g.days.map(d=>`<button class="overview-day ${d.id===dayId?'selected-day':''}" data-day="${d.id}" aria-current="${d.id===dayId?'date':'false'}"><strong>${esc(d.label)}</strong><span>${esc(d.date||'Date needed')}</span><small>Unit ${esc(d.unit||'—')} · ${d.schedule.length} schedule items${d.lockedRevisionId?' · Issued':''}</small></button>`).join('')}</div></section>`).join('')||'<p class="empty">No shooting days. Add a day with + or restore a deleted day.</p>'}</div>`,[]);}
async function changeDay(command,stack=undoDays){
 const before=clone(project),oldSelected=dayId;const oldOrder=Days.ordered(project.days),index=oldOrder.findIndex(d=>d.id===dayId);
 const inverse=Days.apply(project,command);if(!project.days.some(d=>d.id===dayId))dayId=Days.ordered(project.days)[Math.min(Math.max(index,0),project.days.length-1)]?.id;
 mark();try{await flush();}catch(e){project=before;dayId=oldSelected;mark();render();throw e;}
 stack.push(inverse);revealDay();render();return inverse;
}
function dayActions(id){const d=project.days.find(d=>d.id===id);if(!d)return;modal('Shooting day actions',`<p><b>${esc(d.label)}</b> · ${esc(d.date||'Date needed')} · Unit ${esc(d.unit)}</p>`,[{label:'Change Date',run:async()=>dateDialog(id)},{label:'Delete',run:async()=>deleteDay(id)}]);}
function dateDialog(id){const d=project.days.find(d=>d.id===id);if(!d)return;modal('Change shooting date',`<p>${esc(d.label)} keeps its identity, calls, schedule and layout. The sidebar and overview sort by date; equal dates keep production order. Issued PDFs retain their original date and bytes. This day's weather approval resets.</p><label class="field">New shooting date<input id="change-day-date" type="date" min="1900-01-01" max="2100-12-31" value="${esc(d.date)}"></label>`,[{label:'Change Date',primary:true,run:async()=>{await changeDay({kind:'date',id,date:$('change-day-date').value});redoDays=[];closeModal();renderSide();}}]);}
async function deleteDay(id){const d=project.days.find(d=>d.id===id);if(!d)return;const remove=async suppress=>{await changeDay({kind:'delete',id});redoDays=[];if(suppress)writePreference('confirm-day-deletion',false);closeModal();renderSide();toast('Day moved to Deleted days. Restore it there or use Undo day change.');};if(readPreference('confirm-day-deletion',true)===false)return remove(false);
 modal('Delete shooting day?',`<p>Move <b>${esc(d.label)}</b> (${esc(d.date||'Date needed')}, Unit ${esc(d.unit)}) to Deleted days?</p><p>Only this day leaves the active schedule. Its calls, schedule, layout and IDs are retained for restoration, including after reopening. Production cast, crew, scenes, locations, other shooting days and all original issued PDFs remain. Restore from Deleted days or use Undo day change.</p><label class="check"><input id="suppress-day-warning" type="checkbox"> Don't show again</label><p class="tiny">Settings → Reset Warnings restores this confirmation.</p>`,[{label:'Delete shooting day',primary:true,run:async()=>remove($('suppress-day-warning').checked)}]);
}
function showDeletedDays(){modal('Deleted shooting days',`<p>Days are retained in this project and its exported archive. Restoring retains the original day ID, contents and issued links.</p>${(project.deletedDays||[]).map(d=>`<article class="deleted-day"><div><strong>${esc(d.label)}</strong><p>${esc(d.date||'Date needed')} · Unit ${esc(d.unit)} · ${d.schedule.length} schedule items · ${d.calls.length} calls</p></div><button data-restore-day="${d.id}">Restore ${esc(d.label)}</button></article>`).join('')||'<p class="empty">No deleted shooting days.</p>'}`,[]);}
$('days-overview').onclick=()=>transition(async()=>daysOverview());$('deleted-days').onclick=()=>transition(async()=>showDeletedDays());
$('undo-day').onclick=()=>transition(async()=>{const command=undoDays.at(-1);if(command){await changeDay(command,redoDays);undoDays.pop();renderSide();}});
$('redo-day').onclick=()=>transition(async()=>{const command=redoDays.at(-1);if(command){await changeDay(command,undoDays);redoDays.pop();renderSide();}});
$('days').addEventListener('contextmenu',e=>{const row=e.target.closest('[data-day],[data-day-options]');if(row){e.preventDefault();transition(async()=>dayActions(row.dataset.day||row.dataset.dayOptions));}});
$('days').addEventListener('keydown',e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){const row=e.target.closest('[data-day],[data-day-options]');if(row){e.preventDefault();transition(async()=>dayActions(row.dataset.day||row.dataset.dayOptions));}}});

async function issue(){
 await flush();if(locked()){day().lockedRevisionId=null;mark();await flush();render();toast('New draft created. Earlier issued PDFs remain unchanged.');return;}
 const check=await api.request('review',{projectId:project.id,dayId});
 modal('Review before issue',`<p>Issue a frozen snapshot and preserve its original PDF. Future edits start a new draft.</p>${check.errors.length?'<h3>Required fixes</h3><ul class="issues errors">'+check.errors.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>No blocking errors.</p>'}${check.warnings.length?'<h3>Review notes</h3><ul class="issues">'+check.warnings.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><label class="check"><input type="checkbox" id="ack-warnings"> I reviewed these warnings and approve this revision.</label>':''}`,check.errors.length?[]:[{label:'Issue revision',primary:true,run:async()=>{const ack=!check.warnings.length||$('ack-warnings')?.checked;if(!ack)throw Error('Acknowledge the review notes before issuing.');const state=await api.request('issue',{projectId:project.id,dayId,version,acknowledgeWarnings:ack});closeModal();await useState(state);toast('Revision issued and original PDF preserved locally.');}}]);
}
async function forecastDialog(){await flush();const loc=primaryLocation();modal('Online weather request',`<p>NWS will receive the selected latitude/longitude, your IP address and an app identifier. It covers supported US locations for about seven days. Your project title, cast and crew are not sent.</p><div class="inline-notice">${esc(loc?.name||'No location')}<br>${esc(loc?.latitude??'Missing latitude')}, ${esc(loc?.longitude??'Missing longitude')}<br>${esc(day().date)} / ${esc(effectiveZone())}</div><label class="check"><input id="forecast-consent" type="checkbox"> Allow this single forecast request to NWS.</label><p>Manual weather and offline solar work without permission.</p>`,[{label:'Retrieve forecast',primary:true,run:async()=>{if(!$('forecast-consent').checked)throw Error('Select permission to send this location to NWS.');const state=await api.request('forecast',{projectId:project.id,dayId,consent:true});closeModal();await useState(state);section='weather';render();toast('Forecast cached. Review and approve it before issue.');}}]);}
async function pdfExport(revisionId){await flush();const result=await api.request('exportPDF',{projectId:project.id,dayId,revisionId});if(!result.canceled)toast('PDF saved: '+result.path);}
const actions={
 'availability-cast':()=>transition(async()=>showAvailability('cast')),'availability-crew':()=>transition(async()=>showAvailability('crew')),
 'source-details':()=>{const p=project.productionDesk;if(!p)return;modal('Production Desk source details',`<p>Source ID: ${esc(p.sourceId)}<br>Scenario: ${esc(p.scenarioId)}<br>File SHA-256: ${esc(p.hash)}</p><p>All source categories, breakdowns, script, shots, calendars, scenarios, availability and annotation metadata are retained below. PDF bytes stay in the original .productiondesk file. This view is read-only.</p><pre>${esc(JSON.stringify(p.model,null,2))}</pre>`,[]);},
 'edit-locations':()=>{view='production';master='locations';render();},
 'new-draft':issue,'pdf':()=>pdfExport(),'refresh-preview':refreshPreview,
 'forecast':forecastDialog,
 'manual-weather':()=>{day().weather={mode:'manual',summary:day().weather.summary,approved:false};mark();render();},
 'add-scene':()=>{const id=$('add-scene-select').value,s=project.scenes.find(s=>s.id===id);if(!s)return toast('Choose a scene to add.');day().schedule.push({id:uid(),type:'scene',sceneId:id,description:'',start:'',offset:0,duration:s.durationMinutes||60});s.castIds.forEach(addCall);mark();render();},
 'add-break':()=>{day().schedule.push({id:uid(),type:'meal',sceneId:'',description:'Meal break',start:'12:30',offset:0,duration:30});mark();render();},
 'custom-section':()=>{day().layout.custom.push({title:'Additional information',text:''});mark();render();},
 'add-background':()=>{day().background.push({id:uid(),type:'background',quantity:1,description:'',call:'',notes:''});mark();render();},
 'add-cast':()=>addPerson('cast'),'add-crew':()=>addPerson('crew'),
 'add-location':()=>{project.locations.push({id:uid(),name:'New location',address:'',latitude:null,longitude:null,zone:project.defaults.zone,parking:'',hospital:'',emergencyPhone:'',verified:false});mark();render();},
 'add-scene-master':()=>{project.scenes.push({id:uid(),number:String(project.scenes.length+1),slug:'INT. NEW SET - DAY',synopsis:'',eighths:0,castIds:[],locationId:'',script:'',shots:[],durationMinutes:60});mark();render();}
};
function addPerson(type){project.people.push({id:uid(),name:'New '+(type==='cast'?'performer':'crew member'),type,role:'',department:type==='cast'?'Cast':'Production',character:'',email:'',phone:''});mark();render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 try{
  if(b.hasAttribute('data-modal-cancel'))return closeModal();
  if(b.dataset.modalAction!==undefined){b.disabled=true;try{await modalAction[Number(b.dataset.modalAction)].run();}catch(err){$('modal-error').textContent=err.message;}finally{b.disabled=false;}return;}
  if(b.dataset.mapUse||b.dataset.mapOpen){const [id,kind]=(b.dataset.mapUse||b.dataset.mapOpen).split(':');const index=project.locations.findIndex(l=>l.id===id);if(index<0||!['shoot','parking'].includes(kind))throw Error('Location no longer exists.');const loc=project.locations[index],parking=kind==='parking';if(b.dataset.mapOpen){await flush();return await api.request('openLocationMap',{projectId:project.id,locationId:id,kind});}const info=window.LocationMaps.inspect(loc[parking?'parkingMapsUrl':'mapsUrl']);if(!info.text)throw Error('No usable address text in this link.');const path=`locations.${index}.`+(parking?'parking':'address');put(path,info.text);const input=document.querySelector(`[data-bind="${path}"]`);if(input){input.value=info.text;input.focus();}mark();refreshLocationMapInfo(path);return;}
  if(b.dataset.dayOptions)return transition(async()=>dayActions(b.dataset.dayOptions));
  if(b.dataset.weekStep)return transition(async()=>{const groups=Days.weeks(project.days);const i=groups.findIndex(g=>g.key===visibleWeek);const g=groups[i+Number(b.dataset.weekStep)];if(g)chooseWeek(g.key);});
  if(b.dataset.weekPage){weekPage+=Number(b.dataset.weekPage);return renderSide();}
  if(b.hasAttribute('data-reveal-day')){revealDay();return renderSide();}
  if(b.dataset.chooseWeek)return transition(async()=>{chooseWeek(b.dataset.chooseWeek);closeModal();});
  if(b.dataset.restoreDay)return transition(async()=>{await changeDay({kind:'restore',id:b.dataset.restoreDay});redoDays=[];selectDay(b.dataset.restoreDay);showDeletedDays();});
  if(b.dataset.day)return transition(async()=>{selectDay(b.dataset.day);if($('modal').open)closeModal();});
  if(b.dataset.view)return transition(async()=>{view=b.dataset.view;render();});
  if(b.dataset.section)return transition(async()=>{view='daily';section=b.dataset.section;render();});
  if(b.dataset.master){master=b.dataset.master;await flush();return renderProduction();}
  if(b.dataset.template){day().layout.preset=b.dataset.template;mark();return render();}
  if(b.dataset.sheetReset){delete day().sheetOverrides[b.dataset.sheetReset];mark();return render();}
  if(b.dataset.reset){delete day().overrides[b.dataset.reset];mark();return render();}
  if(b.dataset.action){await actions[b.dataset.action]?.();return;}
  if(b.dataset.move){const [kind,a,delta]=b.dataset.move.split(':'),i=Number(a),j=i+Number(delta),list=kind==='layout'?day().layout.order:day().schedule;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];mark();return render();}
  if(b.dataset.remove){const [kind,i]=b.dataset.remove.split(':');(kind==='custom'?day().layout.custom:kind==='background'?day().background:day().schedule).splice(Number(i),1);mark();return render();}
  if(b.dataset.script){const s=project.scenes.find(s=>s.id===b.dataset.script);modal(s.number+' · '+s.slug,`<p>${esc(s.synopsis)}</p><p class="tiny">Local scene ID: ${esc(s.id)}<br>Source ID: ${esc(s.sourceId||'User-created')}</p>${s.script?'<pre>'+esc(s.script)+'</pre>':'<p>No screenplay text supplied by this source.</p>'}${s.shots?.length?'<h3>Source shots & camera setups</h3>'+s.shots.map(shot=>'<article class="row-card"><p><b>'+esc(shot.number)+' · '+esc(shot.name)+'</b><br>'+esc(shot.description||'')+'</p><p>'+esc(shot.size)+' / Camera '+esc(shot.camera||'—')+' / '+esc(shot.lens)+' mm / '+esc(shot.movement||'')+' / '+esc(shot.equipment||'')+'</p><p>'+esc(shot.day||'Unscheduled')+' · '+esc(shot.status||'')+' · takes '+esc(shot.takes??'')+' · circle '+esc(shot.circleTake||'—')+'<br>Setup '+esc(shot.setupMinutes??'—')+' min / shoot '+esc(shot.shootMinutes??'—')+' min / actual '+esc(shot.actualMinutes||'—')+' min</p><p class="tiny">Shot ID: '+esc(shot.id)+'<br>Source shot ID: '+esc(shot.sourceId||'Not supplied')+'<br>Camera object: '+esc(shot.cameraObjectId||'Not supplied')+'</p><p>'+esc(shot.notes)+'</p></article>').join(''):''}`,[]);return;}
  if(b.dataset.revisionExport)return pdfExport(b.dataset.revisionExport);
  if(b.dataset.revisionPreview){const r=await api.request('revision',{projectId:project.id,revisionId:b.dataset.revisionPreview});modal('Issued R'+r.number,`<p>Issued ${esc(r.issued)}. SHA-256 ${esc(r.hash)}</p><iframe id="revision-frame" sandbox="allow-same-origin" title="Issued revision preview" width="100%" height="500"></iframe>`,[]);$('revision-frame').srcdoc=r.html;}
 }catch(err){error(err);}
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.dataset.attend){if(el.checked)addCall(el.dataset.attend);else day().calls=day().calls.filter(c=>c.personId!==el.dataset.attend);mark();render();}
 if(el.dataset.hide){const k=el.dataset.hide;day().layout.hidden=day().layout.hidden.filter(x=>x!==k);if(!el.checked)day().layout.hidden.push(k);mark();}
 if(el.dataset.sceneCast){const [i,id]=el.dataset.sceneCast.split(':');project.scenes[i].castIds=project.scenes[i].castIds.filter(x=>x!==id);if(el.checked)project.scenes[i].castIds.push(id);mark();}
});
