let productionDeskPreview=null;
function showProductionDeskPreview(r){
 productionDeskPreview=r;const s=r.summary;
 modal(r.targetId?(r.duplicate?'Production already imported':'Review Production Desk update'):'Preview Production Desk import',`<p><b>${esc(s.title)}</b><br>Source production: ${esc(s.sourceId)}</p><label class="field">Schedule scenario<select id="pd-scenario">${options(r.scenarios,r.scenarioId,null)}</select></label><p>${s.scenes} scenes · ${s.cast} characters · ${s.shots} shots · ${s.days.length} shooting days</p><table><thead><tr><th>Day / date</th><th>Scenes in source order</th></tr></thead><tbody>${s.days.map((d,i)=>'<tr><td>Day '+(i+1)+' / '+esc(d.date||'Date required')+'</td><td>'+esc(d.scenes.join(', '))+'</td></tr>').join('')}</tbody></table><p>Unscheduled: ${esc(s.unscheduled.join(', ')||'None')}</p><p>Mapping: characters → cast register and daily cast rows; headings, eighths, script, elements and comments → scenes; selected stripboard → daily schedule; production company, notes and revision colors → defaults. Other scenarios and source metadata remain available in Source details.</p><ul class="issues">${r.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')}</ul>${r.conflicts.length?'<h3>Local values retained ('+r.conflicts.length+')</h3><ul class="issues">'+r.conflicts.slice(0,50).map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul>':''}<p>${r.duplicate?'This exact file is already linked. Opening it makes no data changes.':r.targetId?'Updates unchanged source fields in the linked production. Local edits and issued days are preserved.':'Creates a separate linked production with the G-Casper-style template.'} Import stays local. No sheet is issued or sent. A database recovery backup is created before changes.</p>`,[{label:r.duplicate?'Open existing':r.targetId?'Apply reviewed update':'Import production',primary:true,run:async()=>{const state=await api.request('commitProductionDesk',{token:r.token});closeModal();view='daily';section='overview';dayId=state.project.days[0]?.id;await useState(state);toast(state.duplicate?'Opened existing linked production.':state.importBackup?'Production Desk import saved. Recovery backup: '+state.importBackup:'Production Desk import saved.');}}]);
 $('pd-scenario').onchange=async()=>{try{showProductionDeskPreview(await api.request('previewProductionDesk',{token:r.token,scenarioId:$('pd-scenario').value,currentProjectId:project.id}));}catch(e){$('modal-error').textContent=e.message;}};
}
